import { useEffect, useRef, useState } from 'react'
import { motion, useReducedMotion, useScroll, useTransform } from 'framer-motion'
import images from '../assets/manifest'

/**
 * <Picture />
 * ---------------------------------------------------------------------------
 * One component owns every image rule in the project:
 *   • responsive srcset (WebP + AVIF) generated by scripts/build-images.mjs
 *   • a 24px blur-up LQIP that is painted instantly and fades out on load
 *   • native lazy loading below the fold, eager + high priority for the hero
 *   • clip-path mask reveal when it enters the viewport
 *   • optional Ken Burns (hero) and scroll parallax (section images)
 *
 * Source of every photograph: AI-generated for this prototype (see README
 * "Image credits" — no real patients, no minors, all synthetic).
 */

const EASE = [0.22, 1, 0.36, 1]

/**
 * Stand-in frames. The four keys below do not exist as dedicated photographs
 * yet, so they borrow the closest graded frame. Replace the source files (see
 * README → "Images to replace") and delete the entry to use the real shot.
 */
const ALIASES = {
  'cta-hands': 'hero',
  'volunteers-refresh': 'camp-college',
  'patient-recovering': 'family-waiting',
  'camp-organiser': 'camp-college',
}

export default function Picture({
  name,
  alt,
  className = '',
  imgClassName = '',
  sizes = '100vw',
  priority = false,
  reveal = true,
  parallax = 0,
  kenBurns = false,
  aspect = '4 / 3',
  overlay,
  overlayClassName = 'bg-oxblood/20',
  rounded = '',
  children,
}) {
  const asset = images[name] ?? images[ALIASES[name]]
  const reduced = useReducedMotion()
  const ref = useRef(null)
  const imgRef = useRef(null)
  const [loaded, setLoaded] = useState(false)

  /**
   * Security: only wire the scroll-driven parallax when the caller asked for
   * it. A transformed ancestor permanently promotes the photograph to its own
   * composited layer — 10 full-bleed images would mean 10 large GPU layers, so
   * the default path stays flat and lets the browser discard off-screen tiles.
   */
  const { scrollYProgress } = useScroll({
    target: ref,
    offset: ['start end', 'end start'],
  })
  const y = useTransform(scrollYProgress, [0, 1], [parallax, -parallax])
  const parallaxStyle = !reduced && parallax ? { y, scale: 1.12 } : undefined

  useEffect(() => {
    if (!priority) return
    const img = imgRef.current
    if (img?.complete) setLoaded(true)
  }, [priority])

  if (!asset) {
    // Fail loudly in dev, gracefully in prod.
    return (
      <div
        className={`relative overflow-hidden bg-crimson/10 ${rounded} ${className}`}
        style={{ aspectRatio: aspect }}
        role="img"
        aria-label={alt}
      />
    )
  }

  /* Don't force `relative` when the caller positions the frame itself —
     Tailwind layer order would make .relative win over .absolute. */
  const selfPositioned = /(^|\s)(absolute|fixed|sticky)\b/.test(className)

  const maxSrc = asset.sources.at(-1)
  const srcSetWebp = asset.sources.map((s) => `${s.webp} ${s.w}w`).join(', ')
  const srcSetAvif = asset.sources.map((s) => `${s.avif} ${s.w}w`).join(', ')

  return (
    <motion.div
      ref={ref}
      className={`${selfPositioned ? '' : 'relative'} overflow-hidden ${rounded} ${className}`}
      /* `aspect="auto"` means "let the parent decide" — used for full-bleed
         fills where the wrapper is absolutely positioned. */
      style={aspect === 'auto' ? undefined : { aspectRatio: aspect }}
      initial={reveal && !reduced ? { clipPath: 'inset(0 0 100% 0)' } : false}
      whileInView={reveal && !reduced ? { clipPath: 'inset(0 0 0% 0)' } : undefined}
      viewport={{ once: true, margin: '-12% 0px -12% 0px' }}
      transition={{ duration: 1.1, ease: EASE }}
    >
      {/* blur-up placeholder */}
      <img
        src={asset.lqip}
        alt=""
        aria-hidden="true"
        draggable="false"
        className={`absolute inset-0 h-full w-full scale-105 object-cover blur-xl transition-opacity duration-700 ${
          loaded ? 'opacity-0' : 'opacity-100'
        }`}
      />

      <motion.div
        className="absolute inset-0 h-full w-full"
        style={parallaxStyle}
      >
        <motion.div
          className="h-full w-full"
          initial={false}
          animate={
            kenBurns && !reduced
              ? { scale: [1.04, 1.14] }
              : undefined
          }
          transition={
            kenBurns && !reduced
              ? { duration: 26, ease: 'linear', repeat: Infinity, repeatType: 'reverse' }
              : undefined
          }
        >
          <picture>
            <source type="image/avif" srcSet={srcSetAvif} sizes={sizes} />
            <source type="image/webp" srcSet={srcSetWebp} sizes={sizes} />
            <img
              ref={imgRef}
              src={maxSrc.webp}
              alt={alt}
              width={asset.width}
              height={asset.height}
              sizes={sizes}
              loading={priority ? 'eager' : 'lazy'}
              decoding={priority ? 'sync' : 'async'}
              /* React 18 only passes these through in lowercase form. */
              {...(priority ? { fetchpriority: 'high' } : {})}
              onLoad={() => setLoaded(true)}
              className={`h-full w-full object-cover transition-opacity duration-700 ${
                loaded ? 'opacity-100' : 'opacity-0'
              } ${imgClassName}`}
            />
          </picture>
        </motion.div>
      </motion.div>

      {overlay !== false && (
        <div className={`pointer-events-none absolute inset-0 ${overlayClassName}`} aria-hidden="true" />
      )}
      {overlay}
      {children}
    </motion.div>
  )
}
